import { test } from 'node:test';
import assert from 'node:assert/strict';
import { TokenBucket } from '../bucket.js';
test('refills over time', () => {
  let t = 0;
  const b = new TokenBucket({ capacity: 3, refillPerSecond: 2, now: () => t });
  assert.ok(b.tryTake(3));
  assert.equal(b.tryTake(), false);
  t = 499; assert.equal(b.tryTake(), false);
  t = 500; assert.ok(b.tryTake());
  t = 10_000; assert.ok(b.tryTake(3)); assert.equal(b.tryTake(), false);
});
test('all or nothing', () => {
  let t = 0;
  const b = new TokenBucket({ capacity: 2, refillPerSecond: 1, now: () => t });
  assert.equal(b.tryTake(5), false);
  assert.ok(b.tryTake(2));
});

